<script setup>
import DoctorBadge from './DoctorBadge.vue';import DoctorActions from './DoctorActions.vue';
defineProps({doctors:Array});defineEmits(['changed']);
const initials=name=>name.split(' ').filter(Boolean).map(s=>s[0]).slice(0,2).join('');
</script>
<template><div class="patient-desktop-table doctor-table"><table><thead><tr><th>Doctor</th><th>Specialization</th><th>Contact</th><th>Branch</th><th>Availability</th><th>Status</th><th>Actions</th></tr></thead><tbody><tr v-for="(doctor,index) in doctors" :key="doctor.id"><td><RouterLink class="patient-identity" :to="`/app/doctors/${doctor.id}`"><span class="patient-initials doctor-initials" :class="['violet','blue','mint','amber'][index%4]">{{initials(doctor.full_name)}}</span><span><strong>{{doctor.full_name}}</strong><small>{{doctor.doctor_number}}</small></span></RouterLink></td><td>{{doctor.specialties.map(s=>s.name).join(', ')}}</td><td><span class="block">{{doctor.phone || 'No phone'}}</span><small class="block mt-2 text-blue-700">{{doctor.email || 'No email'}}</small></td><td>{{doctor.branches.map(b=>b.name).join(', ')}}</td><td><DoctorBadge :value="doctor.availability"/></td><td><DoctorBadge :value="doctor.status"/></td><td><div class="flex items-center gap-3"><RouterLink class="btn-secondary" :to="`/app/doctors/${doctor.id}`">View</RouterLink><DoctorActions :doctor="doctor" @changed="$emit('changed')"/></div></td></tr></tbody></table></div><div class="patient-mobile-list"><article v-for="doctor in doctors" :key="doctor.id"><div class="flex items-center justify-between gap-3"><RouterLink class="patient-identity" :to="`/app/doctors/${doctor.id}`"><span class="patient-initials doctor-initials violet">{{initials(doctor.full_name)}}</span><span><strong>{{doctor.full_name}}</strong><small>{{doctor.doctor_number}}</small></span></RouterLink><DoctorActions :doctor="doctor" @changed="$emit('changed')"/></div><p class="mt-4 text-slate-600">{{doctor.specialties.map(s=>s.name).join(', ')}}</p><p class="mt-2 text-sm text-slate-500">{{doctor.branches.map(b=>b.name).join(', ')}}</p><p class="mt-2 text-sm text-slate-500">{{doctor.phone || doctor.email || 'No contact recorded'}}</p><div class="mt-4 flex gap-2"><DoctorBadge :value="doctor.availability"/><DoctorBadge :value="doctor.status"/><RouterLink class="ml-auto back-link" :to="`/app/doctors/${doctor.id}`">View</RouterLink></div></article></div></template>
